using Microsoft.EntityFrameworkCore; using pcms.Application.Inventory; using pcms.Domain.Entities; using pcms.Domain.Inventory; using pcms.Infrastructure.Persistence;
namespace pcms.Infrastructure.Services;
public class UrnInventoryService(AppDbContext db):IUrnInventoryService
{ public async Task<IEnumerable<UrnInventoryDto>> GetAsync(){var xs=await db.UrnSupplyItems.AsNoTracking().Include(x=>x.Urn).Include(x=>x.SupplyItem).Where(x=>x.IsActive).ToListAsync();var ids=xs.Select(x=>x.SupplyItemId).ToArray();var ms=await db.SupplyInventoryMovements.AsNoTracking().Where(x=>ids.Contains(x.SupplyItemId)).ToListAsync();return xs.Select(x=>{var q=ms.Where(m=>m.SupplyItemId==x.SupplyItemId).Sum(m=>SupplyInventoryMovementEffects.Apply(m.MovementType,m.Quantity));return new UrnInventoryDto(x.Id,x.UrnId,x.Urn.Name,x.SupplyItemId,x.SupplyItem.Name,x.SupplyItem.ScanCode,x.SupplyItem.UnitOfMeasure,q,x.SupplyItem.MinimumQuantity,q<=x.SupplyItem.MinimumQuantity);});}
 public async Task<UrnInventoryDto> SaveAsync(UrnSupplyItemInput i){var urn=await db.Urns.FirstOrDefaultAsync(x=>x.Id==i.UrnId&&x.IsActive)??throw new ArgumentException("La urna no existe.");var item=await db.SupplyItems.FirstOrDefaultAsync(x=>x.Id==i.SupplyItemId&&x.IsActive&&x.TrackInventory)??throw new ArgumentException("El insumo debe estar activo y controlar inventario.");if(!new[]{"pieza","pza","unidad","units"}.Contains(item.UnitOfMeasure.ToLowerInvariant()))throw new ArgumentException("El insumo debe usar una unidad compatible con piezas.");if(await db.UrnSupplyItems.AnyAsync(x=>x.SupplyItemId==item.Id&&x.IsActive&&x.UrnId!=urn.Id))throw new InvalidOperationException("El insumo ya está vinculado a otra urna.");await db.UrnSupplyItems.Where(x=>x.UrnId==urn.Id&&x.IsActive).ExecuteUpdateAsync(x=>x.SetProperty(y=>y.IsActive,false));var x=new UrnSupplyItem{Id=Guid.NewGuid(),UrnId=urn.Id,SupplyItemId=item.Id,CreatedAt=DateTime.UtcNow};db.Add(x);await db.SaveChangesAsync();return (await GetAsync()).Single(y=>y.Id==x.Id);}
}
